import java.util.ArrayList;
import java.util.List;

public class AlignedReceiptWriterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String render(List<LineItem> items) {
        try {
            String text = AlignedReceiptWriter.render(items);
            return text == null ? "<null>" : text.replace("\n", "<nl>");
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        List<LineItem> two = new ArrayList<>();
        two.add(new LineItem("apple", 2, 1.5));
        two.add(new LineItem("bread", 1, 3.25));
        String rendered = render(two);
        check("two item receipt",
                "apple       2    3.00<nl>bread       1    3.25<nl>TOTAL       2    6.25<nl>", rendered);
        check("every line is the same width", true, sameWidth(rendered));

        List<LineItem> one = new ArrayList<>();
        one.add(new LineItem("kiwi", 3, 0.5));
        check("single item receipt", "kiwi        3    1.50<nl>TOTAL       1    1.50<nl>", render(one));

        check("empty receipt", "TOTAL       0    0.00<nl>", render(new ArrayList<LineItem>()));

        List<LineItem> longName = new ArrayList<>();
        longName.add(new LineItem("chocolatebar", 1, 2.0));
        check("name longer than the column is not cut",
                "chocolatebar  1    2.00<nl>TOTAL       1    2.00<nl>", render(longName));

        List<LineItem> many = new ArrayList<>();
        many.add(new LineItem("nut", 4, 0.25));
        many.add(new LineItem("bolt", 4, 0.25));
        many.add(new LineItem("washer", 2, 0.5));
        String manyText = render(many);
        check("three item total line", true, manyText.endsWith("TOTAL       3    3.00<nl>"));
        check("three item first line", true, manyText.startsWith("nut         4    1.00<nl>"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static boolean sameWidth(String rendered) {
        String[] lines = rendered.split("<nl>");
        if (lines.length == 0) {
            return false;
        }
        for (String line : lines) {
            if (line.length() != 21) {
                return false;
            }
        }
        return true;
    }
}

