import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.List;
import java.util.Locale;

record LineItem(String name, int qty, double unitPrice) { }

public class AlignedReceiptWriter {

    public static String render(List<LineItem> items) {
        StringWriter target = new StringWriter();
        PrintWriter writer = new PrintWriter(target);
        double grandTotal = 0.0;
        for (LineItem item : items) {
            double lineTotal = item.qty() * item.unitPrice();
            grandTotal += lineTotal;
            writer.printf(Locale.US, "%-10s%3d%8.2f\n", item.name(), item.qty(), lineTotal);
        }
        writer.printf(Locale.US, "%-10s%3d%8.2f\n", "TOTAL", items.size(), grandTotal);
        writer.flush();
        return target.toString();
    }
}
